86	/// residue from a rejected or superseded upload, safe to GC (#33 D6 staged-
87	/// bytes hygiene).
88	pub async fn orphan_staging_keys<S: StagingStore>(store: &S) -> SeamResult<Vec<Vec<u8>>> {
89	    let queued = store.queued_ops().await?;
90	    let mut referenced = std::collections::HashSet::new();
