97	            }
98	            // An undecodable entry dead-letters with its staged bytes preserved
99	            // (#33 D6); its staging key is unknowable, so nothing is safely an
100	            // orphan this pass — fail closed.
101	            Err(_) => return Ok(Vec::new()),
102	        }
103	    }
104	    let orphans = store
105	        .staged_keys()
106	        .await?
107	        .into_iter()
108	        .filter(|key| !referenced.contains(key))
109	        .collect();
110	    Ok(orphans)
111	}
