18	/// A fresh random per-version content key (blueprint/engine.md, #26 D6). The
19	/// terminal owner of the key bytes: zeroized on drop, borrowed (never copied)
20	/// by the seal, which must not zero it (the "zeroize at the terminal owner
21	/// only" rule). One key seals every chunk of a version; a new version mints a
22	/// new key.
23	#[derive(Zeroize, ZeroizeOnDrop)]
24	pub struct ContentKey([u8; KEY_LEN]);
25	
26	impl ContentKey {
27	    /// Mint a fresh content key from injected entropy. Fails closed if entropy
28	    /// acquisition fails — never substitutes predictable bytes. The staging
29	    /// buffer self-zeroizes on every return path (incl. the error path, where
30	    /// it may hold partially-written key bytes).
31	    pub fn generate(entropy: &mut impl Entropy) -> Result<Self, EntropyError> {
32	        let mut bytes = Zeroizing::new([0u8; KEY_LEN]);
33	        entropy.fill(bytes.as_mut())?;
34	        Ok(Self(*bytes))
35	    }
36	
37	    /// Adopt caller-supplied key bytes (a restored per-version key). The array
38	    /// is caller-owned; callers holding secret material zeroize it themselves.
39	    pub fn from_bytes(bytes: [u8; KEY_LEN]) -> Self {
40	        Self(bytes)
41	    }
42	
43	    /// Borrow the raw key bytes for the seal. Borrowed, never taken — the seal
44	    /// leaves this buffer intact.
45	    pub fn as_bytes(&self) -> &[u8; KEY_LEN] {
46	        &self.0
47	    }
48	}
49	
50	// A key must never render its bytes to a log site (security rule 2).
51	impl core::fmt::Debug for ContentKey {
52	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
53	        f.write_str("ContentKey(<redacted>)")
54	    }
55	}
