57	/// One sealed leaf: its content-address and the sealed wire bytes that address
58	/// resolves to.
59	#[derive(Debug, Clone, PartialEq, Eq)]
60	pub struct SealedChunk {
61	    /// The leaf content CID (binary CIDv1, `raw` codec) — a BLAKE3 digest over
62	    /// [`Self::sealed`]. The block's authenticity anchor: a verified read
63	    /// recomputes it and fails closed on mismatch.
64	    pub cid: Vec<u8>,
65	    /// The sealed wire blob `nonce(24) || ciphertext||tag` this CID addresses.
66	    pub sealed: Vec<u8>,
67	}
